import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    tokens = rule.split(" ")
    kind = tokens[0]
    out: list[str] = []

    def add(d: date) -> bool:
        if d >= s:
            out.append(d.isoformat())
        return len(out) >= count

    if kind == "DAILY":
        k = int(tokens[1])
        d = s
        while True:
            if add(d):
                break
            d += timedelta(days=k)

    elif kind == "WEEKLY":
        k = int(tokens[1])
        codes = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
        wds = sorted(codes[c] for c in tokens[2].split(","))
        monday = s - timedelta(days=s.weekday())
        w = 0
        done = False
        while not done:
            base = monday + timedelta(weeks=w * k)
            for wd in wds:
                d = base + timedelta(days=wd)
                if d < s:
                    continue
                if add(d):
                    done = True
                    break
            w += 1

    elif kind == "MONTHLY" and len(tokens) == 3:
        k = int(tokens[1])
        dd = int(tokens[2])
        y, m = s.year, s.month
        while len(out) < count:
            if ((y - s.year) * 12 + (m - s.month)) % k == 0:
                last = calendar.monthrange(y, m)[1]
                if dd == -1:
                    day = last
                elif dd <= last:
                    day = dd
                else:
                    day = None
                if day is not None:
                    if add(date(y, m, day)):
                        break
            m += 1
            if m > 12:
                m = 1
                y += 1

    elif kind == "MONTHLY":
        k = int(tokens[1])
        n = int(tokens[2])
        codes = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
        wd = codes[tokens[3]]
        y, m = s.year, s.month
        while len(out) < count:
            if ((y - s.year) * 12 + (m - s.month)) % k == 0:
                last = calendar.monthrange(y, m)[1]
                if n == -1:
                    days = [dy for dy in range(last, 0, -1) if date(y, m, dy).weekday() == wd]
                    day = days[0]
                else:
                    days = [dy for dy in range(1, last + 1) if date(y, m, dy).weekday() == wd]
                    day = days[n - 1] if n <= len(days) else None
                if day is not None:
                    if add(date(y, m, day)):
                        break
            m += 1
            if m > 12:
                m = 1
                y += 1

    elif kind == "YEARLY":
        k = int(tokens[1])
        mm, dd = (int(x) for x in tokens[2].split("-"))
        y = s.year
        while True:
            if (y - s.year) % k == 0 and dd <= calendar.monthrange(y, mm)[1]:
                if add(date(y, mm, dd)):
                    break
            y += 1

    return out
